post" action="<?= $escape($basePath) ?>/admin/platform/integrations/asaas/sandbox-tests/<?= (int)$t['id'] ?>/cancel" onsubmit="return confirm('Cancelar esta cobrança somente no Sandbox?')"><?= $csrfField ?><button class="button button-danger button-icon" title="Cancelar"><i class="fa-solid fa-trash"></i></button></form><?php endif;?></div></td></tr><?php endforeach;endif;?></tbody></table></div>
